"""``ObjectStorage``: attachments on the local disk or in Amazon S3 (CR-011).

**Keys** are always generated by the server (``object_key``), never taken from the client:
``attachments/<yyyy>/<mm>/<attachment_id>.<ext>``. ``validate_key`` also accepts the bare file
names of the rows created before 2.1.0 (local only).

**Never overwrite:** ``put`` of an existing key succeeds only if the content is the same
(SHA-256), which makes a retry idempotent. Different content raises ``ObjectConflictError``.

**Encryption** (S3): SSE-KMS with the customer-managed key (``S3_KMS_KEY_ID``). This is storage
encryption by AWS, independent of the application encryption (Fernet) used for
``shipment_recipients`` and ``messages``: they share no key. On the local disk the files stay
unencrypted, as before (a risk already recorded in the remediation report).

**Integrity:** S3 checks ``ChecksumSHA256`` on upload, and the object carries ``sha256`` in its
metadata so migration and retries can compare without downloading it.
"""

import asyncio
import base64
import hashlib
import os
import re
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path
from typing import TYPE_CHECKING, Any, Protocol
from uuid import UUID

from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError

from app.shared import metrics

if TYPE_CHECKING:
    from mypy_boto3_s3 import S3Client

_KEY = re.compile(
    r"^(attachments/\d{4}/\d{2}/)?[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(pdf|jpg)$"
)


class StorageError(Exception):
    """The backend failed (network, permissions, KMS…): 503 ALMACENAMIENTO_NO_DISPONIBLE."""


class ObjectConflictError(StorageError):
    """The key already holds different content: it is never overwritten."""


@dataclass(frozen=True)
class ObjectInfo:
    size: int
    sha256: str | None


def object_key(attachment_id: UUID | str, extension: str, created_at: datetime) -> str:
    return f"attachments/{created_at.year:04d}/{created_at.month:02d}/{attachment_id}.{extension}"


def validate_key(key: str) -> str:
    if not _KEY.match(key):
        raise ValueError("clave de objeto inválida")
    return key


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


class ObjectStorage(Protocol):
    backend: str

    async def put(self, key: str, data: bytes, *, content_type: str, sha256: str) -> None: ...

    async def get(self, key: str) -> bytes: ...

    async def head(self, key: str) -> ObjectInfo | None: ...

    async def delete(self, key: str) -> None: ...

    async def presigned_get(
        self, key: str, *, filename: str, content_type: str, ttl: int
    ) -> str | None: ...


class LocalObjectStorage:
    backend = "local"

    def __init__(self, root: Path) -> None:
        self._root = root

    def _path(self, key: str) -> Path:
        path = (self._root / validate_key(key)).resolve()
        if self._root.resolve() not in path.parents:  # defence in depth: never leave the root
            raise ValueError("clave fuera del directorio de adjuntos")
        return path

    async def put(self, key: str, data: bytes, *, content_type: str, sha256: str) -> None:
        path = self._path(key)
        if path.exists():
            if sha256_hex(path.read_bytes()) != sha256:
                raise ObjectConflictError(key)
            return
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_bytes(data)
        os.replace(tmp, path)  # atomic: a reader never sees half a file

    async def get(self, key: str) -> bytes:
        path = self._path(key)
        if not path.exists():
            raise StorageError(f"objeto no encontrado: {key}")
        return path.read_bytes()

    async def head(self, key: str) -> ObjectInfo | None:
        path = self._path(key)
        if not path.exists():
            return None
        data = path.read_bytes()
        return ObjectInfo(size=len(data), sha256=sha256_hex(data))

    async def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)

    async def presigned_get(
        self, key: str, *, filename: str, content_type: str, ttl: int
    ) -> str | None:
        return None  # local files are only served through the API


class S3ObjectStorage:
    backend = "s3"

    def __init__(self, client: "S3Client", bucket: str, kms_key_id: str) -> None:
        self._s3, self._bucket, self._kms = client, bucket, kms_key_id

    async def _call(self, operation: str, fn: Any, **kwargs: Any) -> Any:
        with metrics.timer("StorageLatency", backend="s3", operation=operation):
            try:
                return await asyncio.to_thread(fn, Bucket=self._bucket, **kwargs)
            except ClientError:
                raise
            except BotoCoreError as error:  # network, credentials, endpoint
                metrics.emit("InfrastructureErrors", 1, component="s3", operation=operation)
                raise StorageError(type(error).__name__) from error

    async def put(self, key: str, data: bytes, *, content_type: str, sha256: str) -> None:
        validate_key(key)
        try:
            await self._call(
                "put",
                self._s3.put_object,
                Key=key,
                Body=data,
                ContentType=content_type,
                ServerSideEncryption="aws:kms",
                SSEKMSKeyId=self._kms,
                ChecksumSHA256=base64.b64encode(bytes.fromhex(sha256)).decode(),
                Metadata={"sha256": sha256},
                IfNoneMatch="*",  # conditional write: S3 refuses to replace an existing key
            )
        except ClientError as error:
            code = error.response.get("Error", {}).get("Code", "")
            if code in ("PreconditionFailed", "ConditionalRequestConflict"):
                existing = await self.head(key)
                if existing is not None and existing.sha256 == sha256:
                    return  # same content: an idempotent retry
                raise ObjectConflictError(key) from error
            metrics.emit("InfrastructureErrors", 1, component="s3", operation="put")
            raise StorageError(code or "ClientError") from error

    async def get(self, key: str) -> bytes:
        try:
            response = await self._call("get", self._s3.get_object, Key=validate_key(key))
        except ClientError as error:
            metrics.emit("InfrastructureErrors", 1, component="s3", operation="get")
            raise StorageError(
                error.response.get("Error", {}).get("Code", "ClientError")
            ) from error
        body: bytes = await asyncio.to_thread(response["Body"].read)
        return body

    async def head(self, key: str) -> ObjectInfo | None:
        try:
            response = await self._call("head", self._s3.head_object, Key=validate_key(key))
        except ClientError as error:
            if error.response.get("Error", {}).get("Code") in ("404", "NoSuchKey", "NotFound"):
                return None
            metrics.emit("InfrastructureErrors", 1, component="s3", operation="head")
            raise StorageError(
                error.response.get("Error", {}).get("Code", "ClientError")
            ) from error
        return ObjectInfo(
            size=int(response["ContentLength"]), sha256=response.get("Metadata", {}).get("sha256")
        )

    async def delete(self, key: str) -> None:
        try:
            await self._call("delete", self._s3.delete_object, Key=validate_key(key))
        except ClientError as error:
            metrics.emit("InfrastructureErrors", 1, component="s3", operation="delete")
            raise StorageError(
                error.response.get("Error", {}).get("Code", "ClientError")
            ) from error

    async def presigned_get(
        self, key: str, *, filename: str, content_type: str, ttl: int
    ) -> str | None:
        url: str = await asyncio.to_thread(
            self._s3.generate_presigned_url,
            "get_object",
            Params={
                "Bucket": self._bucket,
                "Key": validate_key(key),
                "ResponseContentDisposition": f'attachment; filename="{filename}"',
                "ResponseContentType": content_type,
            },
            ExpiresIn=ttl,
        )
        return url


# SigV4 is mandatory to download SSE-KMS objects with a presigned URL (SigV2 fails). Retries
# are bounded ("standard" mode, 3 attempts): no infinite retry against S3.
S3_CLIENT_CONFIG = Config(signature_version="s3v4", retries={"max_attempts": 3, "mode": "standard"})


def build_storage(settings: Any, *, client: Any = None) -> ObjectStorage:
    """From the settings; an S3 client can be injected (tests with moto)."""
    if settings.attachments_storage == "local":
        return LocalObjectStorage(settings.attachments_dir)
    if not settings.s3_bucket or not settings.s3_kms_key_id:
        raise RuntimeError("ATTACHMENTS_STORAGE=s3 requiere S3_BUCKET y S3_KMS_KEY_ID")
    if client is None:
        import boto3

        client = boto3.client("s3", region_name=settings.aws_region, config=S3_CLIENT_CONFIG)
    return S3ObjectStorage(client, settings.s3_bucket, settings.s3_kms_key_id)
